import sys
import json
import subprocess
import os

def validate_checks_file(file_path):
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
            if not isinstance(data, list):
                return False
            return all(isinstance(item, dict) and 'name' in item and 'command' in item and 'expect' in item
                      for item in data)
    except (IOError, json.JSONDecodeError):
        return False

def run_checks(file_path):
    if not validate_checks_file(file_path):
        print(f"Error: Invalid JSON file format or missing required fields.", file=sys.stderr)
        sys.exit(2)

    with open(file_path, 'r') as f:
        checks = json.load(f)

    for check in checks:
        name = check['name']
        command = check['command']
        expect_expr = check['expect']

        try:
            result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
            out = result.stdout
        except subprocess.CalledProcessError as e:
            print(f"Error running command '{command}': {e}", file=sys.stderr)
            sys.exit(2)

        try:
            if eval(expect_expr, {'out': out}):
                print(f"PASS {name}")
            else:
                print(f"FAIL {name}")
        except Exception as e:
            print(f"Error evaluating check '{name}': {e}", file=sys.stderr)
            sys.exit(2)

    sys.exit(0)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Error: Missing JSON file argument.", file=sys.stderr)
        sys.exit(2)

    run_checks(sys.argv[1])

import sys
import json
import subprocess
import os

def main():
    if len(sys.argv) != 2:
        print("Error: JSON file path argument missing.", file=sys.stderr)
        sys.exit(2)

    try:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)
    except (IOError, json.JSONDecodeError):
        print("Error: Could not read or parse JSON file.", file=sys.stderr)
        sys.exit(2)

    if not isinstance(data, list):
        print("Error: JSON file must contain an array of objects.", file=sys.stderr)
        sys.exit(2)

    all_passed = True

    for item in data:
        if not isinstance(item, dict) or 'name' not in item or 'command' not in item or 'expect' not in item:
            print(f"Error: Invalid object format in JSON: {item}", file=sys.stderr)
            sys.exit(2)

        name = item['name']
        command = item['command']
        expect_expr = item['expect']

        try:
            result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
            out = result.stdout.strip()
        except subprocess.CalledProcessError as e:
            print(f"Error executing command '{command}': {e.stderr}", file=sys.stderr)
            sys.exit(2)

        try:
            if eval(f"out == {expect_expr}", {'out': out}):
                print(f"PASS {name}")
            else:
                print(f"FAIL {name}")
                all_passed = False
        except Exception as e:
            print(f"Error evaluating expression '{expect_expr}': {e}", file=sys.stderr)
            sys.exit(2)

    sys.exit(0 if all_passed else 1)

if __name__ == "__main__":
    main()

import json
import subprocess
import sys

def run_checks(json_path):
    with open(json_path, 'r') as f:
        tests = json.load(f)

    for test in tests:
        name = test['name']
        command = test['command']
        expect = test['expect']

        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        out = result.stdout.strip()

        try:
            expr_result = eval(expect, {'__builtins__': None}, {'out': out})
            if expr_result:
                print(f"PASS {name}")
            else:
                print(f"FAIL {name}")
        except Exception as e:
            print(f"FAIL {name} (Error evaluating expression: {str(e)})")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python runchecks.py <json_file_path>")
        sys.exit(1)

    run_checks(sys.argv[1])
